      --color-text: #e0e0e0;
      --color-muted-text: #a0a0a0;
      --color-border: #333333;
      --color-focus: #5a8dff;
      --color-btn-bg: #1e1e1e;
      --color-btn-hover: #2a2a2a;
    }

    body {
      background-color: var(--color-bg);
      color: var(--color-text);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
      line-height: 1.6;
      padding: 2rem;
      max-width: 800px;
      margin: 0 auto;
    }

    h1 {
      color: var(--color-text);
      font-size: 2.25rem;
      margin-bottom: 2rem;
      font-weight: 700;
