<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
  <title>Cat FAQ</title>
  <style>
    :root {
      --color-bg: #121212;
      --color-text: #e0e0e0;
      --color-muted-text: #a0a0a0;
      --color-border: #333333;
      --color-focus: #5a8dff;
      --color-btn-bg: #1e1e1e;
      --color-btn-hover: #2a2a2a;
    }

    body {
      background-color: var(--color-bg);
      color: var(--color-text);
      font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
      line-height: 1.6;
      padding: 2rem;
      max-width: 800px;
      margin: 0 auto;
    }

    h1 {
      color: var(--color-text);
      font-size: 2.25rem;
      margin-bottom: 2rem;
      font-weight: 700;
    }

    /* Wrap each question/answer section in a div with class "example" */
    .example {
      border: 1px solid var(--color-border);
      border-radius: 8px;
      margin-bottom: 1rem;
      background: var(--color-btn-bg);
      overflow: hidden;
    }

    .example h3 {
      margin: 0;
    }

    .example button {
      appearance: none;
      width: 100%;
      text-align: left;
      background: transparent;
      color: var(--color-text);
      border: none;
      padding: 1.25rem;
      font-size: 1.125rem;
      font-weight: 600;
      cursor: pointer;
      display: flex;
      justify-content: space-between;
      align-items: center;
      transition: background 0.2s ease;
      font-family: inherit;
    }

    .example button:hover {
      background: var(--color-btn-hover);
    }

    .example button:focus-visible {
      outline: 2px solid transparent;
      box-shadow: inset 0 0 0 2px var(--color-bg), inset 0 0 0 4px var(--color-focus);
    }

    /* Container for the controlled content has a class of "details" */
    .details {
      padding: 0 1.25rem 1.25rem 1.25rem;
      color: var(--color-text);
      background: var(--color-btn-bg);
    }

    .details p {
      margin: 0;
      color: var(--color-muted-text);
    }

    .icon {
      width: 1.25rem;
      height: 1.25rem;
      transition: transform 0.2s ease;
      fill: currentColor;
      flex-shrink: 0;
      margin-left: 1rem;
    }

    .example button[aria-expanded="true"] .icon {
      transform: rotate(180deg);
    }

    @media (forced-colors: active) {
      .example button:focus-visible {
        outline: 2px solid ButtonText;
        box-shadow: none;
      }
      .example {
        border: 1px solid ButtonBorder;
      }
      .details {
        border-top: 1px solid ButtonBorder;
      }
    }
  </style>
</head>
<body>
  <div id="root"></div>

  <!-- React & ReactDOM -->
  <script src="https://unpkg.com/react@18/umd/react.production.min.js" crossorigin></script>
  <script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js" crossorigin></script>
  <!-- Babel Standalone to compile JSX in the browser -->
  <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>

  <script type="text/babel">
    const { useState } = React;

    const catFaqs = [
      {
        id: 'purr',
        question: 'Why do cats purr?',
        answer: 'Cats purr for various reasons. While it\'s commonly associated with contentment and relaxation, they may also purr when they are stressed, in pain, or self-soothing. The frequency of purring has been shown to promote healing and tissue regeneration.'
      },
      {
        id: 'sleep',
        question: 'How many hours a day do cats sleep?',
        answer: 'On average, adult cats sleep 12 to 16 hours a day. Kittens and older cats may sleep even more, up to 20 hours. This extensive sleeping pattern helps them conserve energy for hunting.'
      },
      {
        id: 'knead',
        question: 'Why do cats knead?',
        answer: 'Kneading, sometimes called "making biscuits," is an instinctual behavior carried over from kittenhood when they kneaded their mother to stimulate milk flow. Adult cats often knead when they are feeling happy, safe, and comfortable.'
      }
    ];

    const FAQItem = ({ question, answer }) => {
      const [isOpen, setIsOpen] = useState(false);

      return (
        <div className="example">
          <h2>
            <button 
              type="button" 
              aria-expanded={isOpen} 
              onClick={() => setIsOpen(!isOpen)}
            >
              {question}
              <svg className="icon" aria-hidden="true" viewBox="0 0 24 24">
                <path d="M7 10l5 5 5-5z" />
              </svg>
            </button>
          </h2>
          <div className="details" hidden={!isOpen}>
            <p>{answer}</p>
          </div>
        </div>
      );
    };

    const App = () => {
      return (
        <main>
          <h1>Cat FAQ</h1>
          {catFaqs.map(faq => (
            <FAQItem key={faq.id} question={faq.question} answer={faq.answer} />
          ))}
        </main>
      );
    };

    const root = ReactDOM.createRoot(document.getElementById('root'));
    root.render(<App />);
  </script>
</body>
</html>', path=None, possible_paths=None, possible_urls=None, read_only=None, reason=None, server_name=None, subject=None, tool_args=None, tool_call_id='function-call-14a2f903-e277-4656-8661-b384b5f7cc02', tool_description=None, tool_name=None, tool_title=None, url=None, warning=None)

